
'''Return exactly:
  "high_revenue_products" → product names whose total revenue is >= revenue_limit
   "highest_selling_product" → product with the highest total number of units sold
   "total_revenue" → revenue generated by all products
   
   Constraints
  - Use .items()
  - One outer for loop
  - Inner loop for sales is allowed
  - Calculate sales totals manually
  - Manually track highest-selling product
  - No sum(), max(), sorted(), or list comprehensions
  - No previous functions
  - Do not modify products
  - No print() inside the function
  - Return exactly the three required keys'''

products = {
    "laptop": {"price": 1200, "sales": [2, 3, 1]},
    "mouse": {"price": 25, "sales": [5, 4, 6]},
    "keyboard": {"price": 80, "sales": [2, 1, 3]},
    "monitor": {"price": 450, "sales": [1, 2, 2]},
    "webcam": {"price": 100, "sales": [3, 2, 4]}
}

def get_sales_details(products, revenue_limit):
    high_revenue_products = []
    highest_selling_product = ''
    total_revenue = 0
    highest_sales = float('-inf')

    for key,value in products.items():
        total_sales = 0
        for sale in value['sales']:
            total_sales += sale

        product_revenue = total_sales * value['price']
        total_revenue += product_revenue

        if product_revenue >= revenue_limit:
            high_revenue_products.append(key)

        if total_sales > highest_sales:
            highest_sales = total_sales
            highest_selling_product = key

    return {

        "high_revenue_products": high_revenue_products,
        "highest_selling_product": highest_selling_product,
        'total_revenue': total_revenue
        
      }
print(get_sales_details(products, 3000))